  function formatDate(d){return new Date(d+'T00:00:00').toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit'})}

  const oldAssign=window.assignEmployeeByDrop;
  if(typeof oldAssign==='function')window.assignEmployeeByDrop=function(employeeId,type,date){const e=employees.find(x=>x.id===employeeId);normalizeEmployee(e);if(e?.availabilityStatus==='red')return alert(`${e.first} ${e.last} ist aktuell nicht einplanbar.`);if(e&&!qualifications(e).includes(type))return alert(`Qualifikationswarnung: ${e.first} ${e.last} besitzt keine Freigabe für ${type}.`);if(isAbsent(employeeId,date))return alert(`${e.first} ${e.last} ist an diesem Tag abwesend und kann nicht eingeplant werden.`);const rhythm=window.sfRhythmCheck?.(e,type,date);if(rhythm?.mode==='required'&&!rhythm.allowed)return alert(`${e.first} ${e.last} kann laut verbindlichem Rhythmus nicht für ${type} eingeplant werden. ${rhythm.reason}.`);return oldAssign.apply(this,arguments)};
  const oldPool=window.renderPlanEmployeePool;
  if(typeof oldPool==='function')window.renderPlanEmployeePool=function(){oldPool();document.querySelectorAll('#planEmployeePool .employee-drag').forEach(card=>{const e=employees.find(x=>x.id===card.dataset.employeeId);if(!e)return;normalizeEmployee(e);const info=card.querySelector('.employee-pool-info');if(!info)return;info.querySelector('.sp-pool-meta')?.remove();const av=availability(e),meta=document.createElement('div');meta.className='sp-pool-meta';meta.innerHTML=`${e.planningTeam?`<span class="sp-pool-team">Team ${esc(e.planningTeam)}</span>`:''}<span class="sp-pool-hours">${Number(e.weeklyHours||0)} h/Woche</span><span class="sp-pool-state ${av.cls}">${av.label}</span>`;info.appendChild(meta);card.style.opacity=av.key==='red'?'.55':''})};
  const oldEmployeeRender=window.renderEmployees;
  if(typeof oldEmployeeRender==='function')window.renderEmployees=function(){const r=oldEmployeeRender.apply(this,arguments);normalizeAll();renderList();renderProfile();return r};
  function ensureLegacyCompatibility(){const root=shell();if(!root||root.querySelector('#employeeSummary'))return;const legacy=root.querySelector('[aria-hidden="true"]');if(!legacy)return;legacy.insertAdjacentHTML('beforeend',`<div id="employeeSummary"></div><div id="employeeAbsences"></div><span id="formTitle"></span><div id="shiftChecks"></div><div id="qualificationChecks"></div><select id="workTimeModel"><option value="SHIFT">Schichtarbeit</option><option value="STANDARD">Feste Arbeitszeit</option><option value="FLEXIBLE">Flexible Schichten</option><option value="ON_CALL">Arbeit auf Abruf</option></select>${['firstName','lastName','personnelNo','role','employment','weeklyHours','startDate','contractEnd','status','birthDate','email','phone','address','zip','city','note'].map(id=>`<input id="${id}">`).join('')}`)}
